begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_function('public','submit_customer_payment_claim',array['uuid','uuid','bigint','jsonb','text','uuid'],'One reported receipt supports several invoices');
select has_function('public','apply_customer_credit',array['uuid','uuid','jsonb','uuid'],'Customer credit can be applied later');
select has_function('public','refund_customer_credit',array['uuid','uuid','bigint','text','date','payment_method','uuid'],'Customer credit can be refunded');

create function pg_temp.aid(n integer) returns uuid language sql immutable as $$select ('cc000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email) values(pg_temp.aid(1),'allocation-owner@example.invalid');
insert into public.organizations(id,name,slug) values(pg_temp.aid(10),'Allocation tests','allocation-tests');
insert into public.memberships(org_id,user_id,role) values(pg_temp.aid(10),pg_temp.aid(1),'owner');
insert into public.clients(id,org_id,name) values(pg_temp.aid(20),pg_temp.aid(10),'Buyer'),(pg_temp.aid(21),pg_temp.aid(10),'Other buyer');
insert into public.invoices(id,org_id,client_id,number) select pg_temp.aid(n),pg_temp.aid(10),case when n=33 then pg_temp.aid(21) else pg_temp.aid(20) end,'DRAFT-A-'||n from generate_series(30,33) n;
insert into public.invoice_items(org_id,invoice_id,description,unit_price_satang) select pg_temp.aid(10),pg_temp.aid(n),'Service',10000 from generate_series(30,33) n;
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.aid(1))::text,true);
set local role authenticated;
select public.update_business_profile(pg_temp.aid(10),'Seller','Address',null,'not_registered');
select public.issue_invoice(org_id,id,version,gen_random_uuid()) from public.invoices where org_id=pg_temp.aid(10);
select lives_ok($$select public.submit_customer_payment_claim(pg_temp.aid(10),pg_temp.aid(20),25000,'[{"invoice_id":"cc000000-0000-4000-8000-000000000030","amount_satang":10000},{"invoice_id":"cc000000-0000-4000-8000-000000000031","amount_satang":10000}]','One transfer',pg_temp.aid(50))$$,'One report reserves two invoices plus excess');
select throws_ok($$select public.submit_internal_payment_claim(pg_temp.aid(10),pg_temp.aid(30),1,'Competing transfer',pg_temp.aid(51))$$,'P0001','Report exceeds unclaimed open balance','Single-invoice report honors multi-invoice reservations');
select public.review_payment_claim_with_evidence(pg_temp.aid(10),(select id from public.payment_claims where org_id=pg_temp.aid(10)),25000,'Bank statement',pg_temp.aid(52),'verified',current_date,'transfer');
select is((select count(*) from public.payments where org_id=pg_temp.aid(10)),1::bigint,'One transfer is one cash receipt');
select is((select count(*) from public.payment_allocations where org_id=pg_temp.aid(10)),2::bigint,'Receipt has two allocations');
select is((select credit_satang from public.client_balances where client_id=pg_temp.aid(20)),5000::bigint,'Excess is unallocated customer credit');
select is((select sum(paid_satang)::bigint from public.invoice_balances where org_id=pg_temp.aid(10)),20000::bigint,'Only allocated cash settles invoices');
select lives_ok($$select public.apply_customer_credit(pg_temp.aid(10),pg_temp.aid(20),'[{"invoice_id":"cc000000-0000-4000-8000-000000000032","amount_satang":2000}]',pg_temp.aid(53))$$,'Existing credit applies to another invoice');
select lives_ok($$select public.apply_customer_credit(pg_temp.aid(10),pg_temp.aid(20),'[{"invoice_id":"cc000000-0000-4000-8000-000000000032","amount_satang":2000}]',pg_temp.aid(53))$$,'Allocation retry is idempotent');
select is((select count(*) from public.payments where org_id=pg_temp.aid(10)),1::bigint,'Credit application does not create cash again');
select throws_ok($$select public.apply_customer_credit(pg_temp.aid(10),pg_temp.aid(20),'[{"invoice_id":"cc000000-0000-4000-8000-000000000033","amount_satang":1000}]',pg_temp.aid(54))$$,'P0001','Issued invoice for receipt customer required','Cannot allocate across customers');
select throws_ok($$select public.apply_customer_credit(pg_temp.aid(10),pg_temp.aid(20),'[{"invoice_id":"cc000000-0000-4000-8000-000000000032","amount_satang":4000}]',pg_temp.aid(55))$$,'P0001','Insufficient customer credit','Cannot spend more than remaining credit');
select lives_ok($$select public.refund_customer_credit(pg_temp.aid(10),(select id from public.payments where org_id=pg_temp.aid(10)),1000,'Bank refund',current_date,'transfer',pg_temp.aid(56))$$,'Unallocated credit refunds as negative cash');
select is((select sum(amount_satang)::bigint from public.payments where org_id=pg_temp.aid(10) and verification_state='verified'),24000::bigint,'Net verified cash includes refund');
select is((select credit_satang from public.client_balances where client_id=pg_temp.aid(20)),2000::bigint,'Refund reduces customer credit');
select throws_ok($$select public.reverse_payment(pg_temp.aid(10),(select id from public.payments where org_id=pg_temp.aid(10) and amount_satang>0),'Bounced transfer',current_date,pg_temp.aid(57))$$,'P0001','Reverse customer refunds before reversing their source receipt','Refund evidence must be offset before source cash');
select lives_ok($$select public.reverse_payment(pg_temp.aid(10),(select id from public.payments where org_id=pg_temp.aid(10) and amount_satang<0),'Wrong refund',current_date,pg_temp.aid(58))$$,'Refund can itself be reversed');
select public.issue_credit_note(pg_temp.aid(10),pg_temp.aid(30),jsonb_build_array(jsonb_build_object('invoice_item_id',(select id from public.invoice_items where invoice_id=pg_temp.aid(30)),'amount_satang',4000)),'Returned service',pg_temp.aid(59));
select is((select credit_satang from public.client_balances where client_id=pg_temp.aid(20)),7000::bigint,'Credit on paid invoice releases cash for reuse');
select is((select paid_satang from public.invoice_balances where invoice_id=pg_temp.aid(30)),6000::bigint,'Paid allocations release the credited portion');
select lives_ok($$select public.reverse_payment(pg_temp.aid(10),(select id from public.payments where org_id=pg_temp.aid(10) and amount_satang=25000),'Bounced transfer',current_date,pg_temp.aid(60))$$,'Reversal follows every later allocation funded by receipt');
select is((select sum(amount_satang)::bigint from public.payments where org_id=pg_temp.aid(10)),0::bigint,'Reversal restores net cash to zero');
select is((select sum(paid_satang)::bigint from public.invoice_balances where org_id=pg_temp.aid(10)),0::bigint,'Reversal offsets all three invoices');
select is((select credit_satang from public.client_balances where client_id=pg_temp.aid(20)),0::bigint,'No credit survives receipt reversal');
select * from finish();
rollback;
